class Book:
    def __init__(self, title, author, isbn):
        self.title = title
        self.author = author
        self.isbn = isbn
        self.is_borrowed = False
    def __str__(self):
        status = "已借出" if self.is_borrowed else "可借"
        return f"《{self.title}》- {self.author} (ISBN: {self.isbn}) [{status}]"
class Library:
    def __init__(self):
        self.books = []
    def add_book(self, book):
        self.books.append(book)
        print(f"已添加图书：{book.title}")
    def borrow_book(self, isbn):
        for book in self.books:
            if book.isbn == isbn:
                if not book.is_borrowed:
                    book.is_borrowed = True
                    print(f"成功借出：{book.title}")
                    return True
                else:
                    print(f"《{book.title}》已被借出")
                    return False
        print("未找到该图书")
        return False
    def return_book(self, isbn):
        for book in self.books:
            if book.isbn == isbn:
                if book.is_borrowed:
                    book.is_borrowed = False
                    print(f"成功归还：{book.title}")
                    return True
                else:
                    print(f"《{book.title}》未被借出")
                    return False
        print("未找到该图书")
        return False
    @property
    def available_books(self):
        return [book for book in self.books if not book.is_borrowed]
    def __len__(self):
        return len(self.books)
# 使用示例
library = Library()
library.add_book(Book("Python编程", "张三", "001"))
library.add_book(Book("数据分析", "李四", "002"))
library.add_book(Book("机器学习", "王五", "003"))
print(f"\n图书馆共有{len(library)} 本书")
print("\n可借图书：")
for book in library.available_books:
    print(book)
library.borrow_book("001")
library.return_book("001")

from pathlib import Path
import time
def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} 执行时间: {end-start:.4f}秒")
        return result
    return wrapper
def read_numbers(filename):
    path = Path(filename)
    try:
        if not path.exists():
            raise FileNotFoundError(f"文件{filename} 不存在")
        with path.open('r') as f:
            for line in f:
                try:
                    yield float(line.strip())
                except ValueError:
                    continue
    except Exception as e:
        print(f"读取文件错误: {e}")
def running_average(numbers):
    total = 0
    count = 0
    for num in numbers:
        total += num
        count += 1
        yield total / count
@timer
def process_data(filename):
    numbers = read_numbers(filename)
    averages = running_average(numbers)
    return list(averages)
# 使用示例
# 创建测试文件
test_file = Path('numbers.txt')
test_file.write_text('10\n20\n30\n40\n50')
result = process_data('numbers.txt')
print(f"移动平均值: {result}")

from functools import wraps
import time
def compose(*functions):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            for f in reversed(functions):
                result = f(result)
            return result
        return wrapper
    return decorator
def retry(times=3, exceptions=(Exception,)):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    if attempt == times - 1:
                        raise
                    print(f"尝试{attempt + 1} 失败: {e}")
                    time.sleep(1)
        return wrapper
    return decorator
def curry(func):
    @wraps(func)
    def wrapper(x):
        def inner(y):
            return func(x, y)
        return inner
    return wrapper
# 使用示例
@compose(lambda x: x * 2, lambda x: x + 10)
def base_value():
    return 5
print(f"组合函数结果: {base_value()}")
# (5 + 10) * 2 = 30
@retry(times=3, exceptions=(ValueError,))
def unstable_function():
    import random
    if random.random() < 0.7:
        raise ValueError("随机错误")
    return "成功"
try:
    result = unstable_function()
    print(f"重试函数结果: {result}")
except ValueError:
    print("所有重试都失败了")
@curry
def add(x, y):
    return x + y
add_5 = add(5)
print(f"柯里化结果: {add_5(3)}")
# 8

