import time
# 通用装饰器
def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__}耗时: {end-start:.4f}秒")
        return result
    return wrapper
# A. 装饰普通函数
@timer
def slow_function():
    time.sleep(0.1)
    return "完成"
slow_function()
# B. 装饰类方法
class MyClass:
    @timer
    def method(self):
        time.sleep(0.1)
        return "方法完成"
obj = MyClass()
obj.method()
# C. 装饰类
def add_str_method(cls):
    cls.__str__ = lambda self: f"{cls.__name__}实例"
    return cls
@add_str_method
class Person:
    pass
print(Person())
# Person实例
# D. 装饰生成器
@timer
def slow_generator():
    for i in range(3):
        time.sleep(0.01)
        yield i
for val in slow_generator():
    print(val)
知识拓展：装饰器的高级应用：
• 带参数的装饰器
• 类装饰器（使用 __call__ ）
• 多个装饰器叠加
• functools.wraps保留元数据

两空依次为 functools 模块和 wraps 装饰器，写作 @functools.wraps(func)。
作用：装饰器返回的 wrapper 会顶替原函数，导致 func.__name__、__doc__、__module__、__annotations__ 等元数据变成 wrapper 的。@wraps(func) 把这些信息复制到 wrapper 上，并设置 __wrapped__ 指向原函数，调试和文档工具才不会认错。
from functools import wraps
def deco(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
@deco
def f():
    "文档"
print(f.__name__)   # f（不加 wraps 会是 wrapper）
print(f.__doc__)    # 文档
注意：@wraps 要写在 wrapper 定义之前、紧挨着 wrapper；它本质是 functools.update_wrapper 的便捷用法。

