from abc import ABC, abstractmethod

class Employee(ABC):
    def __init__(self, name, emp_id, base_salary):
        self._name = name
        self._emp_id = emp_id
        self._base_salary = base_salary

    @property
    def name(self):
        return self._name

    @property
    def emp_id(self):
        return self._emp_id

    @abstractmethod
    def calculate_salary(self):
        pass

    def __str__(self):
        return f"{self.name} (ID: {self.emp_id})"

    def __repr__(self):
        return (f"{self.__class__.__name__}('{self.name}', "
                f"'{self.emp_id}', {self._base_salary})")

    def __eq__(self, other):
        if isinstance(other, Employee):
            return self.emp_id == other.emp_id
        return False

class Manager(Employee):
    def __init__(self, name, emp_id, base_salary, bonus):
        super().__init__(name, emp_id, base_salary)
        self.bonus = bonus

    def calculate_salary(self):
        return self._base_salary + self.bonus

class Developer(Employee):
    def __init__(self, name, emp_id, base_salary, project_count):
        super().__init__(name, emp_id, base_salary)
        self.project_count = project_count

