from pathlib import Path
import shutil
import hashlib

def organize_by_extension(source_dir, target_dir):
    source = Path(source_dir)
    target = Path(target_dir)
    target.mkdir(parents=True, exist_ok=True)
    file_count = 0
    for file in source.rglob('*'):
        if file.is_file():
            ext = file.suffix[1:] if file.suffix else 'no_extension'
            ext_dir = target / ext
            ext_dir.mkdir(exist_ok=True)
            dest_file = ext_dir / file.name
            try:
                shutil.copy2(file, dest_file)
                file_count += 1
                print(f"已复制: {file.name} -> {ext}/")
            except Exception as e:
                print(f"复制失败{file.name}: {e}")
    print(f"\n共组织{file_count} 个文件")

def get_file_hash(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def find_duplicates(directory):
    path = Path(directory)
    size_map = {}
    # 按大小分组
    for file in path.rglob('*'):
        if file.is_file():
            size = file.stat().st_size
            if size not in size_map:
                size_map[size] = []
            size_map[size].append(file)
    # 检查相同大小的文件
    for size, files in size_map.items():
        if len(files) > 1:
            hash_map = {}
            for file in files:
                file_hash = get_file_hash(file)
                if file_hash not in hash_map:
                    hash_map[file_hash] = []
                hash_map[file_hash].append(file)
            for file_hash, dup_files in hash_map.items():
                if len(dup_files) > 1:
                    yield dup_files

def clean_empty_dirs(directory):
    path = Path(directory)
    removed_count = 0
    for dir_path in sorted(path.rglob('*'), reverse=True):
        if dir_path.is_dir():
            try:
                if not any(dir_path.iterdir()):
                    dir_path.rmdir()
                    removed_count += 1
                    print(f"已删除空目录: {dir_path}")
            except Exception as e:
                print(f"删除失败{dir_path}: {e}")
    print(f"\n共删除{removed_count} 个空目录")

