import time
class ConfigManager:
    _instance = None
    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance
    def __init__(self, config_file=None):
        if not hasattr(self, '_initialized'):
            self._config = {}
            self._config_file = None
            self._last_modified = None
            if config_file:
                self.load_config(config_file)
            self._initialized = True
    def load_config(self, config_file):
        path = Path(config_file)
        if not path.exists():
            raise FileNotFoundError(f"配置文件{config_file} 不存在")
        with path.open('r', encoding='utf-8') as f:
            self._config = json.load(f)
        self._config_file = path
        self._last_modified = path.stat().st_mtime
        print(f"已加载配置: {config_file}")
    def reload_if_modified(self):
        if self._config_file:
            current_mtime = self._config_file.stat().st_mtime
            if current_mtime > self._last_modified:
                print("检测到配置文件变化，重新加载...")
                self.load_config(self._config_file)
    def get(self, key, default=None):
        self.reload_if_modified()
        keys = key.split('.')
        value = self._config
        for k in keys:
            if isinstance(value, dict) and k in value:
                value = value[k]
            else:
                return default
        return value
    @property
    def config(self):
        self.reload_if_modified()
        return self._config
def require_config(key):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            config = ConfigManager()
            if config.get(key) is None:
                raise ValueError(f"缺少配置项: {key}")
            return func(*args, **kwargs)
        return wrapper
    return decorator
