from functools import wraps
import time
def pipeline_step(func):
    @wraps(func)
    def wrapper(data):
        start = time.time()
        if not hasattr(data, '__len__'):
            data = list(data)
        input_size = len(data)
        result = func(data)
        if hasattr(result, '__len__'):
            output_size = len(result)
        elif hasattr(result, '__iter__'):
            result = list(result)
            output_size = len(result)
        else:
            output_size = 1
        end = time.time()
        print(f"步骤{func.__name__}:")
        print(f"  输入: {input_size} 项")
        print(f"  输出: {output_size} 项")
        print(f"  耗时: {end-start:.4f}秒")
        return result
    return wrapper
class Pipeline:
    def __init__(self):
        self.steps = []
    def add_step(self, step_func):
        self.steps.append(step_func)
        return self
    def execute(self, data):
        result = data
        for step in self.steps:
            result = step(result)
        return result
def filter_data(condition):
    @pipeline_step
    def filter_step(data):
        for item in data:
            if condition(item):
                yield item
    return filter_step
def transform_data(func):
    @pipeline_step
    def transform_step(data):
        for item in data:
            yield func(item)
    return transform_step
def aggregate_data(func):
    @pipeline_step
    def aggregate_step(data):
        return func(list(data))
    return aggregate_step
