import heapq
import logging
from abc import ABC, abstractmethod
from enum import Enum
from functools import wraps

logging.basicConfig(level=logging.INFO, format='%(message)s')
logger = logging.getLogger(__name__)


class TaskStatus(Enum):
    PENDING = '待执行'
    RUNNING = '执行中'
    COMPLETED = '已完成'
    FAILED = '失败'


def retry_on_failure(max_retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            for attempt in range(1, max_retries + 1):
                try:
                    return func(self, *args, **kwargs)
                except Exception:
                    logger.warning('任务 %s 第 %d 次失败', self.name, attempt)
                    if attempt == max_retries:
                        self.status = TaskStatus.FAILED
                        raise
        return wrapper
    return decorator


class Task(ABC):
    def __init__(self, name, priority=0):
        self.name = name
        self.priority = priority
        self.status = TaskStatus.PENDING

    @abstractmethod
    def execute(self):
        ...

    def __lt__(self, other):
        return self.priority > other.priority

    def __repr__(self):
        return f'Task({self.name}, p={self.priority}, {self.status.value})'


class DataTask(Task):
    def __init__(self, name, data, priority=0):
        super().__init__(name, priority)
        self.data = data

    @retry_on_failure(3)
    def execute(self):
        self.status = TaskStatus.RUNNING
        result = sum(self.data)
        self.status = TaskStatus.COMPLETED
        return result


class EmailTask(Task):
    def execute(self):
        self.status = TaskStatus.RUNNING
        self.status = TaskStatus.COMPLETED
        return f'发送给 {self.name}'


class Scheduler:
    def __init__(self):
        self.queue = []
        self.done = []

    def add_task(self, task):
        heapq.heappush(self.queue, task)

    def run_next(self):
        if not self.queue:
            return None
        task = heapq.heappop(self.queue)
        try:
            result = task.execute()
            self.done.append(task)
            return result
        except Exception as exc:
            logger.error('任务失败: %s', exc)
            return None

    def run_all(self):
        while self.queue:
            self.run_next()

    def pending_tasks(self):
        for task in self.queue:
            if task.status == TaskStatus.PENDING:
                yield task

import pickle
import time
from collections import OrderedDict
from functools import wraps
from pathlib import Path


class LRUCache:
    def __init__(self, capacity=128):
        self.capacity = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return None
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)

    def __getitem__(self, key):
        return self.get(key)

    def __setitem__(self, key, value):
        self.put(key, value)

    def __len__(self):
        return len(self.data)


class CacheDecorator:
    def __init__(self, ttl=None):
        self.ttl = ttl
        self.cache = {}
        self.hits = 0
        self.misses = 0

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            now = time.time()
            if key in self.cache:
                value, ts = self.cache[key]
                if self.ttl is None or now - ts < self.ttl:
                    self.hits += 1
                    return value
                del self.cache[key]
            self.misses += 1
            value = func(*args, **kwargs)
            self.cache[key] = (value, now)
            return value
        wrapper.stats = lambda: (self.hits, self.misses)
        return wrapper


class FileCache:
    def __init__(self, root):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)

    def _path(self, key):
        return self.root / (str(hash(key)) + '.pkl')

    def get(self, key):
        p = self._path(key)
        if not p.exists():
            return None
        with p.open('rb') as f:
            return pickle.load(f)

    def put(self, key, value):
        with self._path(key).open('wb') as f:
            pickle.dump(value, f)


class MultiLevelCache:
    def __init__(self, l1_size=16, root='./cache'):
        self.l1 = LRUCache(l1_size)
        self.l2 = FileCache(root)

    def get(self, key):
        value = self.l1.get(key)
        if value is not None:
            return value
        value = self.l2.get(key)
        if value is not None:
            self.l1.put(key, value)
        return value

    def put(self, key, value):
        self.l1.put(key, value)
        self.l2.put(key, value)

from pathlib import Path
import hashlib
import shutil


class FileSyncer:
    def __init__(self, src, dst, exts=None, min_size=0):
        self.src = Path(src)
        self.dst = Path(dst)
        self.exts = set(exts) if exts else None
        self.min_size = min_size

    def _ok(self, p):
        return p.is_file() and (not self.exts or p.suffix in self.exts) and p.stat().st_size >= self.min_size

    def scan_directory(self, root):
        for p in Path(root).rglob('*'):
            if self._ok(p):
                yield p

    @staticmethod
    def digest(p):
        h = hashlib.sha256()
        with Path(p).open('rb') as f:
            for chunk in iter(lambda: f.read(65536), b''):
                h.update(chunk)
        return h.hexdigest()

    def find_differences(self):
        src = {p.relative_to(self.src): p for p in self.scan_directory(self.src)}
        dst = {p.relative_to(self.dst): p for p in self.scan_directory(self.dst)}
        added = [k for k in src if k not in dst]
        changed = [k for k in src.keys() & dst.keys() if self.digest(src[k]) != self.digest(dst[k])]
        removed = [k for k in dst if k not in src]
        return added, changed, removed

    def sync_files(self, dry_run=False):
        added, changed, removed = self.find_differences()
        for rel in added + changed:
            if not dry_run:
                target = self.dst / rel
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(self.src / rel, target)
            yield ('copy', rel)
        for rel in removed:
            if not dry_run:
                (self.dst / rel).unlink(missing_ok=True)
            yield ('delete', rel)


syncer = FileSyncer('./src_dir', './dst_dir', exts={'.py', '.txt'})
for action, rel in syncer.sync_files(dry_run=True):
    print(action, rel)

import importlib
from abc import ABC, abstractmethod


class Plugin(ABC):
    name = 'plugin'
    version = '0.1'
    description = ''

    @abstractmethod
    def initialize(self):
        ...

    @abstractmethod
    def execute(self, *args, **kwargs):
        ...

    @abstractmethod
    def cleanup(self):
        ...


class PluginManager:
    def __init__(self):
        self.plugins = {}

    def register(self, cls):
        obj = cls()
        self.plugins[obj.name] = obj
        return cls

    def load_module(self, module_name):
        mod = importlib.import_module(module_name)
        for obj in vars(mod).values():
            if isinstance(obj, type) and issubclass(obj, Plugin) and obj is not Plugin:
                self.register(obj)

    def run(self, name, *args, **kwargs):
        plugin = self.plugins[name]
        plugin.initialize()
        try:
            return plugin.execute(*args, **kwargs)
        finally:
            plugin.cleanup()


