import copy
from functools import wraps
def log_operation(func):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        # 保存操作前的状态
        state = copy.deepcopy(list(self))
        self._history.append(('before', state, func.__name__))
        # 执行操作
        result = func(self, *args, **kwargs)
        # 保存操作后的状态
        state = copy.deepcopy(list(self))
        self._history.append(('after', state, func.__name__))
        print(f"操作: {func.__name__}, 参数: {args}")
        return result
    return wrapper
class SafeList(list):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._history = []
        self._frozen = False
    def _check_frozen(self):
        if self._frozen:
            raise RuntimeError("列表已被冻结，不能修改")
    @log_operation
    def append(self, item):
        self._check_frozen()
        super().append(item)
    @log_operation
    def extend(self, iterable):
        self._check_frozen()
    super().extend(iterable)
@log_operation
def insert(self, index, item):
    self._check_frozen()
    super().insert(index, item)
@log_operation
def remove(self, item):
    self._check_frozen()
    super().remove(item)
@log_operation
def pop(self, index=-1):
    self._check_frozen()
    return super().pop(index)
def undo(self):
    if len(self._history) < 2:
        print("没有可撤销的操作")
        return
    # 找到最后一个'before'状态
    for i in range(len(self._history) - 1, -1, -1):
        if self._history[i][0] == 'before':
            state = self._history[i][1]
            self.clear()
            self.extend(state)
            print(f"撤销操作: {self._history[i][2]}")
            break
def get_history(self):
    return [(op, name) for op, _, name in self._history]
def deep_copy(self):
    return copy.deepcopy(self)
def shallow_copy(self):
    return SafeList(self)
    def safe_append(self, item, max_size=None):
        if max_size and len(self) >= max_size:
            raise ValueError(f"列表大小已达到限制: {max_size}")
        self.append(item)
    def freeze(self):
        self._frozen = True
        print("列表已冻结")
    def unfreeze(self):
        self._frozen = False
        print("列表已解冻")
