import copy
import inspect
from functools import wraps

MUTABLES = (list, dict, set)


def safe_mutable_default(func):
    sig = inspect.signature(func)

    @wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind_partial(*args, **kwargs)
        for name, param in sig.parameters.items():
            if name not in bound.arguments and isinstance(param.default, MUTABLES):
                bound.arguments[name] = type(param.default)()
        return func(*bound.args, **bound.kwargs)
    return wrapper


def immutable_params(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        args = tuple(copy.deepcopy(a) if isinstance(a, MUTABLES) else a for a in args)
        kwargs = {k: copy.deepcopy(v) if isinstance(v, MUTABLES) else v for k, v in kwargs.items()}
        return func(*args, **kwargs)
    return wrapper


