        'type': type(obj).__name__,
        'mutable': is_mutable(obj),
        'size': sys.getsizeof(obj),
        'length': len(obj) if hasattr(obj, '__len__') else None,
    }


def find_mutable_elements(container):
    if isinstance(container, dict):
        return [(k, type(v).__name__) for k, v in container.items() if is_mutable(v)]
    return [(i, type(v).__name__) for i, v in enumerate(container) if is_mutable(v)]


def calculate_memory_usage(obj):
    size = sys.getsizeof(obj)
    if isinstance(obj, (list, tuple, set)):
        size += sum(calculate_memory_usage(x) for x in obj)
    elif isinstance(obj, dict):
        size += sum(calculate_memory_usage(k) + calculate_memory_usage(v) for k, v in obj.items())
    return size


