import threading
from pathlib import Path


class Config:
    def __init__(self, data=None):
        self._data = copy.deepcopy(data or {})
        self._lock = threading.RLock()

    def get(self, path, default=None):
        cur = self._data
        for part in path.split('.'):
            if not isinstance(cur, dict) or part not in cur:
                return default
            cur = cur[part]
        return cur

    def set(self, path, value):
        new = Config(self._data)
        cur = new._data
        parts = path.split('.')
        for part in parts[:-1]:
            cur = cur.setdefault(part, {})
        cur[parts[-1]] = copy.deepcopy(value)
        return new

    def diff(self, other):
        out = {}
        def walk(a, b, prefix=''):
            for key in a.keys() | b.keys():
                p = f'{prefix}.{key}' if prefix else key
                if isinstance(a.get(key), dict) and isinstance(b.get(key), dict):
                    walk(a[key], b[key], p)
                elif a.get(key) != b.get(key):
                    out[p] = (a.get(key), b.get(key))
        walk(self._data, other._data)
        return out

    def save(self, path):
        Path(path).write_text(json.dumps(self._data, ensure_ascii=False, indent=2), encoding='utf-8')

    @classmethod
    def load(cls, path):
        return cls(json.loads(Path(path).read_text(encoding='utf-8')))


class ConfigHistory:
    def __init__(self, initial=None):
        self._lock = threading.RLock()
        self._versions = [copy.deepcopy(initial._data) if initial else {}]

    def commit(self, cfg):
        with self._lock:
            self._versions.append(copy.deepcopy(cfg._data))

    def rollback(self, index=-1):
        with self._lock:
            return Config(copy.deepcopy(self._versions[index]))

from collections.abc import Mapping


class FrozenDict(Mapping):
    def __init__(self, data):
        self._data = dict(data)
    def __getitem__(self, key):
        return self._data[key]
    def __iter__(self):
        return iter(self._data)
    def __len__(self):
        return len(self._data)
    def __hash__(self):
        return hash(frozenset(self._data.items()))


def mutable_to_immutable(obj, _memo=None):
    if _memo is None:
        _memo = {}
    oid = id(obj)
    if oid in _memo:
        if _memo[oid] == 'converting':
            raise ValueError('检测到循环引用')
        return _memo[oid]
    if isinstance(obj, (str, bytes, int, float, bool, type(None), frozenset)):
        return obj
    if isinstance(obj, list):
        _memo[oid] = 'converting'
        out = tuple(mutable_to_immutable(x, _memo) for x in obj)
        _memo[oid] = out
        return out
    if isinstance(obj, dict):
        _memo[oid] = 'converting'
        out = FrozenDict({k: mutable_to_immutable(v, _memo) for k, v in obj.items()})
        _memo[oid] = out
        return out
    if isinstance(obj, set):
        _memo[oid] = 'converting'
        out = frozenset(mutable_to_immutable(x, _memo) for x in obj)
        _memo[oid] = out
        return out
    return obj


def list_to_tuple(lst, deep=False):
    return tuple(mutable_to_immutable(x) for x in lst) if deep else tuple(lst)


def tuple_to_list(tpl, deep=False):
    return [mutable_to_immutable(x) for x in tpl] if deep else list(tpl)


def dict_to_frozendict(d):
    return FrozenDict({k: mutable_to_immutable(v) for k, v in d.items()})


def validate_immutable(obj, _seen=None):
    if _seen is None:
        _seen = set()
    if id(obj) in _seen:
        return True
    _seen.add(id(obj))
    if isinstance(obj, (list, dict, set, bytearray)):
        return False
    if isinstance(obj, (tuple, frozenset, FrozenDict)):
        vals = obj.values() if isinstance(obj, Mapping) else obj
        return all(validate_immutable(v, _seen) for v in vals)
    return True

