class VersionedData:
    def __init__(self, data=None):
        self.current = copy.deepcopy(data if data is not None else {})
        self.history = [copy.deepcopy(self.current)]
        self.version = 1

    def update(self, changes):
        self.history.append(copy.deepcopy(self.current))
        self.current.update(copy.deepcopy(changes))
        self.version += 1
        return self.version

    def rollback(self, version):
        target = self.history[version - 1]
        self.history.append(copy.deepcopy(self.current))
        self.current = copy.deepcopy(target)
        self.version = len(self.history)
        return self.current

