        for key in self.current.keys() | other.current.keys():
            p = f'{prefix}.{key}' if prefix else key
            a, b = self.current.get(key), other.current.get(key)
            if isinstance(a, dict) and isinstance(b, dict):
                out.update(VersionedData(a).diff(VersionedData(b), p))
