import copy
from datetime import datetime
from functools import wraps


class MutabilityTracker:
    """包装对象，记录每次修改前后的状态，支持撤销和日志导出。"""

    _MUTATING = {
        list: {'append', 'extend', 'insert', 'remove', 'pop', 'clear', 'sort', 'reverse'},
        dict: {'update', 'setdefault', 'pop', 'popitem', 'clear'},
        set: {'add', 'discard', 'remove', 'pop', 'clear', 'update',
              'intersection_update', 'difference_update',
              'symmetric_difference_update'},
    }

    def __init__(self, obj):
        self._obj = obj
        self._history = []
        self._log = []
        self._record('初始化', copy.deepcopy(obj))

    def _record(self, operation, state_before):
        now = datetime.now().strftime('%H:%M:%S')
        self._history.append({
            'time': now,
            'operation': operation,
            'before': state_before,
            'after': copy.deepcopy(self._obj),
        })
        self._log.append(f'[{now}] {operation}')

    def __getattr__(self, name):
        # 只有正常属性查找失败时才会走到这里，_obj 等属性不受影响
        attr = getattr(self._obj, name)
        if not callable(attr):
            return attr

        mutating_names = self._MUTATING.get(type(self._obj))

        @wraps(attr)
        def wrapper(*args, **kwargs):
            before = copy.deepcopy(self._obj)
            result = attr(*args, **kwargs)
            if mutating_names is None:
                # 自定义对象：状态真的变了才记录
                try:
                    changed = self._obj != before
                except Exception:
                    changed = True
            else:
                changed = name in mutating_names
            if changed:
                args_text = ', '.join(repr(a) for a in args)
                self._record(f'{name}({args_text})', before)
            return result

        return wrapper

    def undo(self):
        if len(self._history) <= 1:
            print('没有可撤销的操作')
            return
        self._history.pop()
        previous = self._history[-1]['after']
        if isinstance(self._obj, list):
            self._obj[:] = previous
        elif isinstance(self._obj, dict):
            self._obj.clear()
            self._obj.update(previous)
        elif isinstance(self._obj, set):
            self._obj.clear()
            self._obj.update(previous)
        else:
            self._obj.__dict__.clear()
            self._obj.__dict__.update(previous.__dict__)
        print(f'已撤销到：{previous!r}')

    def get_history(self):
        return list(self._history)

    def export_log(self, filename=None):
        text = '\n'.join(self._log)
        if filename:
            with open(filename, 'w', encoding='utf-8') as f:
                f.write(text)
            print(f'日志已导出到 {filename}')
        else:
            print(text)
        return text

    def get_obj(self):
        return self._obj

    def __repr__(self):
        return f'MutabilityTracker({self._obj!r})'

