import copy
from functools import wraps


_IMMUTABLE_TYPES = (int, float, complex, str, bytes, bool, type(None), tuple, frozenset)


def _is_mutable(obj):
    """不可变类型返回 False；list/dict/set/自定义对象视为可变。"""
    return not isinstance(obj, _IMMUTABLE_TYPES)


def _copy_if_mutable(obj, deep):
    if not _is_mutable(obj):
        return obj
    return copy.deepcopy(obj) if deep else copy.copy(obj)


def safe_params(deep=False):
    """装饰器：调用前复制可变参数，函数内部怎么改都不影响外部。"""

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            safe_args = [_copy_if_mutable(a, deep) for a in args]
            safe_kwargs = {k: _copy_if_mutable(v, deep) for k, v in kwargs.items()}
            return func(*safe_args, **safe_kwargs)

        return wrapper

    return decorator


def make_immutable(obj):
    """递归转换：list→tuple，set→frozenset，dict→可哈希的键值元组。"""
    if isinstance(obj, list):
        return tuple(make_immutable(x) for x in obj)
    if isinstance(obj, tuple):
        return tuple(make_immutable(x) for x in obj)
    if isinstance(obj, set):
        return frozenset(make_immutable(x) for x in obj)
    if isinstance(obj, dict):
        return tuple(sorted((k, make_immutable(v)) for k, v in obj.items()))
    return obj


def immutable_return(func):
    """装饰器：把返回值递归冻结，转换报告放在 wrapper.last_report。"""

    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        frozen = make_immutable(result)
        wrapper.last_report = {
            'before_type': type(result).__name__,
            'after_type': type(frozen).__name__,
        }
        return frozen

    wrapper.last_report = {}
    return wrapper


def is_deeply_immutable(obj, visited=None):
    """递归判断是否深度不可变；visited 用来处理循环引用。"""
    if visited is None:
        visited = set()
    if isinstance(obj, (int, float, complex, str, bytes, bool, type(None))):
        return True
    obj_id = id(obj)
    if obj_id in visited:
        return True
    visited.add(obj_id)
    if isinstance(obj, (tuple, frozenset)):
        return all(is_deeply_immutable(item, visited) for item in obj)
    return False


def compare_mutability(obj1, obj2):
    """汇总两个对象的可变性信息。"""

    def info(obj):
        return {
            'type': type(obj).__name__,
            'is_mutable': _is_mutable(obj),
            'is_deeply_immutable': is_deeply_immutable(obj),
        }

    return {'obj1': info(obj1), 'obj2': info(obj2)}

