class ImmutableConfig(Mapping):
    """初始化后不可修改的嵌套配置，支持只读字典访问和哈希。"""

    def __init__(self, data):
        object.__setattr__(self, '_data', self._freeze(data))
        object.__setattr__(self, '_hash', None)

    @classmethod
    def _freeze(cls, obj):
        """递归冻结：dict 保持 dict，list/tuple→tuple，set→frozenset。"""
        if isinstance(obj, Mapping):
            return {k: cls._freeze(v) for k, v in obj.items()}
        if isinstance(obj, (list, tuple)):
            return tuple(cls._freeze(x) for x in obj)
        if isinstance(obj, (set, frozenset)):
            return frozenset(cls._freeze(x) for x in obj)
        return obj

    def __getitem__(self, key):
        value = self._data[key]
        if isinstance(value, dict):
            return ImmutableConfig(value)
        return value

    def __iter__(self):
        return iter(self._data)

    def __len__(self):
        return len(self._data)

    def __setitem__(self, key, value):
        raise TypeError('不可变配置不支持修改')

    def __delitem__(self, key):
        raise TypeError('不可变配置不支持删除')

    def __setattr__(self, name, value):
        raise AttributeError('不可变配置不支持修改属性')

    def __delattr__(self, name):
        raise AttributeError('不可变配置不支持删除属性')

    def _to_hashable(self, obj):
        if isinstance(obj, dict):
            return tuple(sorted((k, self._to_hashable(v)) for k, v in obj.items()))
        if isinstance(obj, (list, tuple)):
            return tuple(self._to_hashable(x) for x in obj)
        if isinstance(obj, (set, frozenset)):
            return frozenset(self._to_hashable(x) for x in obj)
        return obj

    def __hash__(self):
        if self._hash is None:
            object.__setattr__(self, '_hash', hash(self._to_hashable(self._data)))
        return self._hash

    def to_dict(self):
        return copy.deepcopy(self._data)

    def __repr__(self):
        return f'ImmutableConfig({self._data!r})'


class ConfigBuilder:
    """构建器：点号路径、深度合并、校验、从 JSON 加载。"""

    def __init__(self):
        self._config = {}
        self._validators = []

    def set(self, key, value):
        keys = key.split('.')
        current = self._config
        for part in keys[:-1]:
            current = current.setdefault(part, {})
        current[keys[-1]] = value
        return self

    def merge(self, other):
        self._deep_merge(self._config, other)
        return self

    def _deep_merge(self, base, update):
        for key, value in update.items():
            if key in base and isinstance(base[key], dict) and isinstance(value, dict):
                self._deep_merge(base[key], value)
            else:
                base[key] = value
        return base

    def add_validator(self, func):
        self._validators.append(func)
        return self

    def validate(self):
        for func in self._validators:
            if not func(self._config):
                raise ValueError(f'配置校验失败：{func.__name__}')
        return self

    def load_from_file(self, filepath):
        path = Path(filepath)
        if path.suffix.lower() == '.json':
            with path.open(encoding='utf-8') as f:
                self.merge(json.load(f))
        return self

    def build(self):
        return ImmutableConfig(self._config)

