import copy
from datetime import datetime


class Snapshot:
    """保存某一时刻对象状态的深拷贝，可恢复或返回副本。"""

    def __init__(self, state, label=''):
        self.state = copy.deepcopy(state)
        self.label = label
        self.time = datetime.now().strftime('%H:%M:%S')

    def restore(self, target=None):
        state = copy.deepcopy(self.state)
        if target is None:
            return state
        if isinstance(target, list):
            target[:] = state
        elif isinstance(target, dict):
            target.clear()
            target.update(state)
        elif isinstance(target, set):
            target.clear()
            target.update(state)
        else:
            target.__dict__.clear()
            target.__dict__.update(state)
        return target

    def diff(self, other):
        """比较两个快照：字典返回变化的键，其他类型返回是否不同。"""
        if isinstance(self.state, dict) and isinstance(other.state, dict):
            keys = set(self.state) | set(other.state)
            return {k for k in keys if self.state.get(k) != other.state.get(k)}
        return self.state != other.state

    def __repr__(self):
        return f'Snapshot({self.label!r}, {self.time}, {self.state!r})'


class SnapshotManager:
    """管理同一对象的多个快照：自动快照、回滚、比较。"""

    def __init__(self, target):
        self.target = target
        self._snapshots = []
        self.snapshot('初始状态')

    def snapshot(self, label=''):
        snap = Snapshot(self.target, label or f'快照{len(self._snapshots) + 1}')
        self._snapshots.append(snap)
        return snap

    def auto_snapshot(self):
        """内容与上一个快照相同就不重复保存，减少存储。"""
        if self._snapshots and self._snapshots[-1].state == copy.deepcopy(self.target):
            return None
        return self.snapshot('自动快照')

    def undo(self):
        if len(self._snapshots) <= 1:
            print('没有可回滚的快照')
            return self.target
        self._snapshots.pop()
        return self._snapshots[-1].restore(self.target)

    def compare(self, i=-2, j=-1):
        return self._snapshots[i].diff(self._snapshots[j])

    def get_snapshots(self):
        return list(self._snapshots)

    def __len__(self):
        return len(self._snapshots)

# 使用示例
data = {'hp': 100, 'gold': 50}
manager = SnapshotManager(data)
data['hp'] = 80
manager.auto_snapshot()
data['gold'] = 30
manager.undo()
print(data)   # {'hp': 80, 'gold': 50}

import re
import warnings

import pandas as pd


class PandasSafetyChecker:
    """对常见 Pandas 操作做安全检查，尽早暴露链式赋值、索引错位等问题。"""

    def __init__(self, df):
        self.df = df
        self.issues = []

    def _add(self, level, message):
        self.issues.append({'level': level, 'message': message})

    def check_schema(self, expected):
        """expected 形如 {'A': 'int64'}；检查缺列、多列和 dtype。"""
        for column, dtype in expected.items():
            if column not in self.df.columns:
                self._add('error', f'缺少列：{column}')
            elif str(self.df[column].dtype) != dtype:
                self._add('warning', f'列 {column} 类型为 {self.df[column].dtype}，期望 {dtype}')
        for column in self.df.columns:
            if column not in expected:
                self._add('warning', f'多出未声明的列：{column}')
        return self

    def check_index(self, other=None):
        """检查重复索引，以及和另一个 DataFrame 的索引是否对齐。"""
        if not self.df.index.is_unique:
            self._add('error', '索引不唯一，按标签对齐可能产生重复行')
        if other is not None and not self.df.index.equals(other.index):
            self._add('warning', '两个 DataFrame 的索引不一致，运算前应先 align')
        return self

    def check_missing(self, threshold=0.3):
        """缺失比例超过阈值时告警。"""
        for column, ratio in self.df.isna().mean().items():
            if ratio > threshold:
                self._add('warning', f'列 {column} 缺失比例 {ratio:.0%}')
        return self

    def safe_assign(self, mask, column, value):
        """用一次 .loc 完成条件赋值，避免 df[mask][column] = value。"""
        if column not in self.df.columns:
            self.df[column] = pd.NA
        self.df.loc[mask, column] = value
        return self.df

    def check_chained_assignment(self, source):
        """静态扫描源码中的链式赋值 df[...][...] = ...。"""
        if re.search(r'\]\s*\[[^\]]*\]\s*=', source):
            self._add('error', '检测到链式赋值，请改成 df.loc[行, 列] = 值')
        return self

    def collect_warnings(self, func, *args, **kwargs):
        """执行操作，把 pandas 的警告收集进问题列表。"""
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = func(*args, **kwargs)
        for item in caught:
            self._add('warning', str(item.message).splitlines()[0])
        return result

    def report(self):
        if not self.issues:
            print('未发现明显问题')
        for issue in self.issues:
            print(f"[{issue['level']}] {issue['message']}")
        return list(self.issues)

# 使用示例
df = pd.DataFrame({'A': [1, 2, 3]})
checker = PandasSafetyChecker(df)
checker.check_chained_assignment("df[df['A'] > 1]['B'] = 100")
checker.safe_assign(df['A'] > 1, 'B', 0)
checker.report()

