class ImmutableData:
    """通用不可变数据类：初始化后不可修改，可哈希，支持 replace()。"""
    __slots__ = ('_data', '_hash')

    def __init__(self, **kwargs):
        # 先把嵌套的 dict/list/set 递归转成不可变形式
        data = {k: self._make_immutable(v) for k, v in kwargs.items()}
        # 用 object.__setattr__ 绕过本类禁止赋值的 __setattr__
        object.__setattr__(self, '_data', data)
        object.__setattr__(self, '_hash', None)

    @staticmethod
    def _make_immutable(value):
        if isinstance(value, ImmutableData):
            return value
        if isinstance(value, dict):
            return ImmutableData(**value)
        if isinstance(value, list):
            return tuple(ImmutableData._make_immutable(v) for v in value)
        if isinstance(value, set):
            return frozenset(ImmutableData._make_immutable(v) for v in value)
        return value

    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        try:
            return self._data[name]
        except KeyError:
            raise AttributeError(
                f"'{type(self).__name__}' object has no attribute '{name}'"
            )

    def __setattr__(self, name, value):
        raise AttributeError("Cannot modify immutable object")

    def __delattr__(self, name):
        raise AttributeError("Cannot modify immutable object")

    def __hash__(self):
        if self._hash is None:
            items = tuple(sorted(self._data.items()))
            object.__setattr__(self, '_hash', hash(self._to_hashable(items)))
        return self._hash

    @staticmethod
    def _to_hashable(obj):
        if isinstance(obj, ImmutableData):
            return ImmutableData._to_hashable(tuple(sorted(obj._data.items())))
        if isinstance(obj, (list, tuple)):
            return tuple(ImmutableData._to_hashable(x) for x in obj)
        if isinstance(obj, dict):
            return tuple(sorted((k, ImmutableData._to_hashable(v))
                                for k, v in obj.items()))
        if isinstance(obj, (set, frozenset)):
            return frozenset(ImmutableData._to_hashable(x) for x in obj)
        return obj

    def __eq__(self, other):
        if not isinstance(other, ImmutableData):
            return NotImplemented
        return self._data == other._data

    def __repr__(self):
        items = ', '.join(f"{k}={v!r}" for k, v in self._data.items())
        return f"ImmutableData({items})"

    def replace(self, **changes):
        """返回修改后的新对象，原对象不变。"""
        new_data = dict(self._data)
        new_data.update(changes)
        return ImmutableData(**new_data)

    def to_dict(self):
        """把内部不可变结构还原成普通 dict / list / set。"""
        def plain(v):
            if isinstance(v, ImmutableData):
                return v.to_dict()
            if isinstance(v, tuple):
                return [plain(x) for x in v]
            if isinstance(v, frozenset):
                return {plain(x) for x in v}
            return v
        return {k: plain(v) for k, v in self._data.items()}


