import sys
import json

IMMUTABLE_TYPES = (int, float, str, bytes, bool, type(None), frozenset)

def is_mutable(obj):
    """基本不可变类型返回 False；元组要递归看元素；其余容器视为可变。"""
    if isinstance(obj, IMMUTABLE_TYPES):
        return False
    if isinstance(obj, tuple):
        return any(is_mutable(item) for item in obj)
    return True

def find_mutable_parts(obj, path="root"):
    """递归找出对象中所有可变部分，返回 path/type/value 列表。"""
    parts = []
    if is_mutable(obj):
        parts.append({
            'path': path,
            'type': type(obj).__name__,
            'value': repr(obj)[:50]
        })
    if isinstance(obj, dict):
        for key, value in obj.items():
            parts.extend(find_mutable_parts(value, f"{path}[{key!r}]"))
    elif isinstance(obj, (list, tuple)):
        for i, item in enumerate(obj):
            parts.extend(find_mutable_parts(item, f"{path}[{i}]"))
    elif isinstance(obj, set):
        for item in obj:
            parts.extend(find_mutable_parts(item, f"{path}.item"))
    return parts

def mutability_report(obj, name="object"):
    """生成一份包含类型、大小、可变部分和修复建议的报告。"""
    report = {
        'name': name,
        'type': type(obj).__name__,
        'is_mutable': is_mutable(obj),
        'size_bytes': sys.getsizeof(obj),
        'mutable_parts': find_mutable_parts(obj, name)
    }
    if report['mutable_parts']:
        report['suggestion'] = "对象包含可变部分，不适合作为字典键或缓存键"
    else:
        report['suggestion'] = "对象完全不可变，可以安全用作字典键"
    return report

def print_mutability_tree(obj, indent=0, name="root"):
    """按缩进打印可变性结构树，最多展开 5 层、每层 5 个元素。"""
    prefix = "  " * indent
    marker = "[可变]" if is_mutable(obj) else "[不可变]"
    print(f"{prefix}{marker} {name}: {type(obj).__name__}")
    if indent >= 5:
        return
    if isinstance(obj, dict):
        for key, value in list(obj.items())[:5]:
            print_mutability_tree(value, indent + 1, repr(key))
    elif isinstance(obj, (list, tuple)):
        for i, item in enumerate(obj[:5]):
            print_mutability_tree(item, indent + 1, f"[{i}]")

def export_report_json(report, filename):
    with open(filename, 'w', encoding='utf-8') as f:
        json.dump(report, f, indent=2, ensure_ascii=False)
    print(f"报告已导出到 {filename}")

# === 使用示例 ===
test_objects = {
    '整数': 42,
    '字符串': "hello",
    '列表': [1, 2, 3],
    '元组': (1, 2, 3),
    '混合元组': ([1, 2], 3),
    '字典': {'a': 1, 'b': [2, 3]},
    'frozenset': frozenset([1, 2, 3])
}
print("基本类型可变性检测:")
for name, obj in test_objects.items():
    print(f"  {'可变' if is_mutable(obj) else '不可变'}  {name}: {type(obj).__name__}")

complex_obj = {
    'name': 'config',
    'values': [1, 2, [3, 4]],
    'settings': {'debug': True, 'data': [[5, 6], [7, 8]]}
}
print("\n可变部分:")
for part in find_mutable_parts(complex_obj):
    print(f"  {part['path']}: {part['type']}")

report = mutability_report(complex_obj, "complex_obj")
print("\n报告:", report['name'], report['type'], report['is_mutable'],
      report['size_bytes'], len(report['mutable_parts']))
print("建议:", report['suggestion'])

print("\n可变性结构树:")
print_mutability_tree(complex_obj)

export_report_json(report, "mutability_report.json")

import copy
import functools

MUTATING_METHODS = {
    'append', 'extend', 'insert', 'remove', 'pop', 'clear', 'sort', 'reverse',
    'add', 'discard', 'update', 'difference_update', 'intersection_update',
    'symmetric_difference_update', 'setdefault', 'popitem',
}

def is_mutable(obj):
    if isinstance(obj, (int, float, str, bytes, bool, type(None), frozenset)):
        return False
    if isinstance(obj, tuple):
        return any(is_mutable(x) for x in obj)
    return True

class ReadOnlyProxy:
    """只读代理：读操作转发给原对象，写方法和下标赋值一律拒绝。"""
    __slots__ = ('_target',)

    def __init__(self, target):
        object.__setattr__(self, '_target', target)

    def __getattr__(self, name):
        attr = getattr(self._target, name)
        if name in MUTATING_METHODS and callable(attr):
            def blocked(*args, **kwargs):
                raise PermissionError(f"参数只读：禁止调用 {name}()")
            return blocked
        return attr

    def __setitem__(self, key, value):
        raise PermissionError("参数只读：禁止修改元素")

    def __delitem__(self, key):
        raise PermissionError("参数只读：禁止删除元素")

    def __getitem__(self, key):
        return self._target[key]

    def __iter__(self):
        return iter(self._target)

    def __len__(self):
        return len(self._target)

    def __repr__(self):
        return repr(self._target)

def readonly_params(func):
    """把可变参数包成只读代理，函数内只能读不能改。"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        safe_args = tuple(ReadOnlyProxy(a) if is_mutable(a) else a for a in args)
        safe_kwargs = {k: ReadOnlyProxy(v) if is_mutable(v) else v
                       for k, v in kwargs.items()}
        return func(*safe_args, **safe_kwargs)
    return wrapper

def copy_params(func):
    """调用前深拷贝所有参数，函数怎么改都碰不到调用者的原对象。"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*copy.deepcopy(args), **copy.deepcopy(kwargs))
    return wrapper

def validate_immutable(func):
    """只要有一个参数含可变对象就直接报错。"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for index, value in enumerate(args):
            if is_mutable(value):
                raise TypeError(f"第 {index} 个位置参数包含可变对象")
        for name, value in kwargs.items():
            if is_mutable(value):
                raise TypeError(f"参数 {name} 包含可变对象")
        return func(*args, **kwargs)
    return wrapper

# === 使用示例 ===
@readonly_params
def try_append(lst):
    lst.append(4)

try:
    try_append([1, 2, 3])
except PermissionError as e:
    print("readonly_params:", e)

@readonly_params
def total(lst):
    return sum(lst)

print("只读也能读:", total([1, 2, 3]))

@copy_params
def mutate(lst):
    lst.append(99)
    return lst

original = [1, 2, 3]
print("copy_params 返回:", mutate(original), "原对象:", original)

@validate_immutable
def make_cache_key(key):
    return key

print("不可变参数通过:", make_cache_key((1, 'a', (2, 3))))
try:
    make_cache_key([1, 2])
except TypeError as e:
    print("validate_immutable:", e)

import ast
import pandas as pd

class PandasOptimizer:
    """检查低效写法，并提供安全赋值与 dtype 优化。"""

    def check_code(self, code):
        issues = []
        tree = ast.parse(code)
        for node in ast.walk(tree):
            targets = []
            if isinstance(node, ast.Assign):
                targets = node.targets
            elif isinstance(node, ast.AugAssign):
                targets = [node.target]
            for target in targets:
                if (isinstance(target, ast.Subscript)
                        and isinstance(target.value, ast.Subscript)):
                    issues.append({
                        'line': node.lineno,
                        'rule': '避免链式索引',
                        'message': "改为 df.loc[条件, '列'] = 值"
                    })
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
                if node.func.attr == 'iterrows':
                    issues.append({
                        'line': node.lineno,
                        'rule': '避免逐行循环',
                        'message': "优先使用向量化运算或 itertuples()"
                    })
        return issues

    @staticmethod
    def safe_assign(df, mask, column, value):
        """用一次 loc 定位完成赋值，避免链式索引。"""
        result = df.copy()
        result.loc[mask, column] = value
        return result

    @staticmethod
    def optimize_dtypes(df):
        """整数/浮点降位宽，低基数 object 列转 category。"""
        result = df.copy()
        for col in result.columns:
            s = result[col]
            if pd.api.types.is_integer_dtype(s):
                result[col] = pd.to_numeric(s, downcast='integer')
            elif pd.api.types.is_float_dtype(s):
                result[col] = pd.to_numeric(s, downcast='float')
            elif (pd.api.types.is_object_dtype(s)
                  or isinstance(s.dtype, pd.StringDtype)):
                if s.nunique(dropna=False) <= max(1, len(s) // 2):
                    result[col] = s.astype('category')
        return result

    @staticmethod
    def memory_report(df):
        before = df.memory_usage(deep=True).sum()
        after = PandasOptimizer.optimize_dtypes(df).memory_usage(deep=True).sum()
        return {'before': int(before), 'after': int(after),
                'saved': f"{(1 - after / before) * 100:.1f}%"}

# === 使用示例 ===
opt = PandasOptimizer()
print(opt.check_code("df[df['A'] > 2]['B'] = 999"))
print(opt.check_code("for i, row in df.iterrows():\n    print(row)"))

