from collections.abc import Mapping
from pathlib import Path


class Config(Mapping):
    def __init__(self, data=None):
        object.__setattr__(
            self, '_data',
            {k: Config(v) if isinstance(v, dict) else v for k, v in (data or {}).items()}
        )

    def __getitem__(self, key):
        return self._data[key]

    def __iter__(self):
        return iter(self._data)

    def __len__(self):
        return len(self._data)

    def __getattr__(self, name):
        try:
            return self._data[name]
        except KeyError:
            raise AttributeError(name)

    def __setattr__(self, name, value):
        raise AttributeError('不可变配置')

    def to_dict(self):
        return {k: v.to_dict() if isinstance(v, Config) else v for k, v in self._data.items()}

    def merge(self, other):
        data = self.to_dict()
        data.update(other.to_dict())
        return Config(data)

    @classmethod
    def from_dict(cls, data):
        return cls(data)

    def save(self, path):
        Path(path).write_text(json.dumps(self.to_dict(), ensure_ascii=False, indent=2), encoding='utf-8')

    @classmethod
    def load(cls, path):
        return cls(json.loads(Path(path).read_text(encoding='utf-8')))


class ConfigBuilder:
    def __init__(self):
        self._data = {}
        self._required = set()

    def set(self, key, value, required=False):
        self._data[key] = value
        if required:
            self._required.add(key)
        return self

    def build(self):
        missing = self._required - self._data.keys()
        if missing:
            raise ValueError(f'缺少必填项: {missing}')
        return Config(self._data)

import copy
import inspect
from functools import wraps
from typing import get_type_hints


def validate_types(func):
    hints = get_type_hints(func)
    sig = inspect.signature(func)

    @wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind(*args, **kwargs)
        for name, value in bound.arguments.items():
            expected = hints.get(name)
            if expected and not isinstance(value, expected):
                raise TypeError(f'{func.__name__}.{name}: 期望 {expected}, 实际 {type(value)}')
        return func(*args, **kwargs)
    return wrapper


def validate_range(min_value=None, max_value=None):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for value in list(args) + list(kwargs.values()):
                if isinstance(value, (int, float)):
                    if min_value is not None and value < min_value:
                        raise ValueError(f'{value} < {min_value}')
                    if max_value is not None and value > max_value:
                        raise ValueError(f'{value} > {max_value}')
            return func(*args, **kwargs)
        return wrapper
    return decorator


def validate_immutable(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        for name, value in kwargs.items():
            if isinstance(value, (list, dict, set)):
                raise TypeError(f'参数 {name} 必须是不可变对象')
        return func(*args, **kwargs)
    return wrapper


def protect_mutable(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        args = tuple(copy.deepcopy(a) if isinstance(a, (list, dict, set)) else a for a in args)
        kwargs = {k: copy.deepcopy(v) if isinstance(v, (list, dict, set)) else v for k, v in kwargs.items()}
        return func(*args, **kwargs)
    return wrapper

import copy
import pickle
from pathlib import Path


class VersionedObject:
    def __init__(self, value=None):
        self.value = copy.deepcopy(value if value is not None else {})
        self.versions = [copy.deepcopy(self.value)]
        self.branches = {'main': copy.deepcopy(self.value)}

    def commit(self, changes):
        self.versions.append(copy.deepcopy(self.value))
        self.value.update(copy.deepcopy(changes))
        self.branches['main'] = copy.deepcopy(self.value)
        return len(self.versions) - 1

    def rollback(self, index):
        self.value = copy.deepcopy(self.versions[index])
        return self.value

    def diff(self, other):
        out = {}
        for key in self.value.keys() | other.value.keys():
            if self.value.get(key) != other.value.get(key):
                out[key] = (self.value.get(key), other.value.get(key))
        return out

    def branch(self, name):
        self.branches[name] = copy.deepcopy(self.value)
        return self.branches[name]

    def merge(self, name):
        current = self.branches['main']
        other = self.branches[name]
        for key, value in other.items():
            if key in current and current[key] != value:
                raise ValueError(f'冲突: {key}')
            current[key] = copy.deepcopy(value)
        self.value = copy.deepcopy(current)
        return self.value

    def save(self, path):
        Path(path).write_bytes(pickle.dumps(self))

    @classmethod
    def load(cls, path):
        return pickle.loads(Path(path).read_bytes())

import copy
import pandas as pd


class SafeDataFrame:
    def __init__(self, df):
        self._df = df.copy(deep=True)
        self._history = []

    @property
    def df(self):
        return self._df.copy(deep=True)

    def assign(self, mask, column, value):
        new = self._df.copy(deep=True)
        new.loc[mask, column] = value
        return SafeDataFrame(new)

    def update(self, changes, inplace=False):
        if inplace:
            self._history.append(self._df.copy(deep=True))
            self._df = self._df.copy(deep=True)
            for key, value in changes.items():
                self._df[key] = value
            return None
        new = self._df.copy(deep=True)
        for key, value in changes.items():
            new[key] = value
        return SafeDataFrame(new)

    def rollback(self):
        if self._history:
            self._df = self._history.pop()
        return self._df
